"""MINEIRINHO — tela inicial Pygame, arte e áudio embutidos.

Coloque ESTE arquivo junto de main.py/app.py/animation.py, fora de assets/.
Prévia: py -3.13 tela_inicial.py
Com o App anterior: py -3.13 tela_inicial.py --jogar

Integração simples:
    from tela_inicial import mostrar_menu
    chefe = mostrar_menu()  # 1, 2, 3; None quando fecha/ESC
    if chefe is not None:
        sua_funcao_que_abre_o_chefe(chefe)

Integração com App/start_level/go_home do projeto anterior:
    from app import App
    from tela_inicial import criar_app_com_menu
    App = criar_app_com_menu(App)  # antes de App(...).run()

Não modifica arquivos nem executa comandos, não baixa nada, não usa Internet.
Só requer pygame. As strings no final são mídias compactadas, não código.
"""
from __future__ import annotations
import base64
from io import BytesIO
import math
from pathlib import Path
import random
import sys
import zlib
import pygame
from config import GAME_TITLE, CREATORS_LABEL

# ---------------- CONFIGURAÇÃO QUE VOCÊ PODE EDITAR ----------------
LARGURA, ALTURA = 1280, 720
TITULO = GAME_TITLE.upper()
NOMES_CHEFES = ('PIRÂMIDE', 'COMILÃO', 'DRAGÃO')
VOLUME_MUSICA = 0.55
FPS_ANIMACAO = 9.0
# Opcional: indique uma fonte sua. None usa a fonte livre já incluída.
FONTE_MENU = None  # Exemplo: 'assets/minha_fonte.ttf'
COR_CREME, COR_OURO, COR_TINTA = '#fff0c3', '#f8d16f', '#291619'
_DADOS = {}


def _midia(nome):
    return zlib.decompress(base64.b64decode(_DADOS[nome]))


class TelaInicial:
    """Menu não bloqueante: handle_event -> update -> draw.

    handle_event retorna 1/2/3 no INICIAR, None nas demais ações.
    encerrado fica True com ESC ou fechar a janela.
    volume é aplicado só à música do menu, em canal reservado.
    O desenho usa o tamanho do destino e mantém a proporção 16:9.
    """
    def __init__(self, *, som=True, nomes=NOMES_CHEFES,
                 disponiveis=(True, True, True), selecionado=1):
        if not pygame.display.get_surface():
            raise RuntimeError('Crie a janela Pygame antes de criar TelaInicial.')
        pygame.font.init()
        self.canvas = pygame.Surface((LARGURA, ALTURA)).convert()
        self.nomes = tuple(nomes)
        self.disponiveis = tuple(disponiveis)
        if len(self.nomes) != 3 or len(self.disponiveis) != 3:
            raise ValueError('Informe exatamente três nomes e disponibilidades.')
        self.selecionado = max(0, min(2, selecionado-1))
        self.foco = -1  # -1: iniciar, 0/1/2: chefes
        self.encerrado = False
        self.tempo = 0.0
        self.fontes, self.textos = {}, {}
        self.som, self.musica, self.canal = som, None, None
        self.aviso_som = ''
        self._buffer_fonte = _midia('fonte.ttf')
        atlas = pygame.image.load(BytesIO(_midia('personagem.webp')), 'atlas.webp').convert_alpha()
        self.frames = []
        cw, ch = atlas.get_width()//3, atlas.get_height()//2
        for n in range(6):
            frame = atlas.subsurface((n%3*cw,n//3*ch,cw,ch)).copy()
            self.frames.append(pygame.transform.smoothscale(frame,(384,384)))
        self.pao = pygame.image.load(BytesIO(_midia('pao.webp')), 'pao.webp').convert_alpha()
        # Se o jogo tem seu próprio sprite, ele tem prioridade sobre o embutido.
        for pasta in (Path(__file__).resolve().parent/'assets',):
            for nome in ('bread.webp', 'bread.png', 'pao_de_queijo.png'):
                caminho=pasta/nome
                if caminho.is_file():
                    self.pao=pygame.image.load(str(caminho)).convert_alpha()
                    break
        self.iniciar_rect=pygame.Rect(395,548,490,68)
        self.nivel_rects=[pygame.Rect(230+i*280,633,260,48) for i in range(3)]
        self.som_rect=pygame.Rect(1133,17,122,34)
        self.fundo=self._criar_fundo()
        self.pilha_fundo, self.pilha_frente=self._criar_paes()
        self.logo=self._criar_logo()
        self.granulados=self._criar_graos()
        self.viewport=pygame.Rect(0,0,LARGURA,ALTURA)
        self.mouse=(-100,-100)
        self._calcular_viewport(pygame.display.get_surface().get_size())

    def fonte(self,tamanho):
        """Carrega e reutiliza a fonte do menu no tamanho solicitado."""
        if tamanho not in self.fontes:
            origem=str(Path(__file__).resolve().parent/FONTE_MENU) if FONTE_MENU else BytesIO(self._buffer_fonte)
            self.fontes[tamanho]=pygame.font.Font(origem,tamanho)
        return self.fontes[tamanho]

    def _texto(self,texto,tamanho,cor=COR_CREME,borda=2):
        chave=(texto,tamanho,cor,borda)
        if chave not in self.textos:
            fonte=self.fonte(tamanho)
            fg=fonte.render(texto,True,cor)
            img=pygame.Surface((fg.get_width()+2*borda,fg.get_height()+2*borda+4),pygame.SRCALPHA)
            contorno=fonte.render(texto,True,COR_TINTA)
            for dx,dy in ((-borda,0),(borda,0),(0,-borda),(0,borda),(-borda,-borda),(borda,borda)):
                img.blit(contorno,(borda+dx,borda+dy+3))
            img.blit(fg,(borda,borda))
            self.textos[chave]=img
        return self.textos[chave]

    def _criar_logo(self):
        img=pygame.Surface((1200,170),pygame.SRCALPHA)
        f=self.fonte(141)
        # Letras levemente arqueadas, como um letreiro de desenho antigo.
        larguras=[f.size(c)[0]-4 for c in TITULO]
        x=(1200-sum(larguras))/2
        for i,c in enumerate(TITULO):
            desvio=(i-(len(TITULO)-1)/2)/max(1,len(TITULO)-1)
            cel=self._texto(c,141,COR_OURO,3)
            cel=pygame.transform.rotate(cel,-desvio*9)
            img.blit(cel,cel.get_rect(midtop=(round(x+larguras[i]/2),round(4+28*desvio**2))))
            x+=larguras[i]
        return img

    def _criar_fundo(self):
        fundo=pygame.Surface((LARGURA,ALTURA)).convert(); fundo.fill('#761e2c')
        centro=(640,395); raio=1700
        for n in range(32):
            a=n*math.tau/32
            cor='#c34140' if n%2==0 else '#8e2634'
            pontos=[centro]+[(centro[0]+math.cos(v)*raio,centro[1]+math.sin(v)*raio)
                            for v in (a,a+math.tau/32+.001)]
            pygame.draw.polygon(fundo,cor,pontos)
        # Vinheta suave, calculada uma única vez em baixa resolução.
        sombra=pygame.Surface((256,144),pygame.SRCALPHA)
        for y in range(144):
            for x in range(256):
                d=math.hypot((x-128)/158,(y-73)/95)
                sombra.set_at((x,y),(26,10,24,min(145,int(max(0,d-.15)*145))))
        fundo.blit(pygame.transform.smoothscale(sombra,(LARGURA,ALTURA)),(0,0))
        pygame.draw.rect(fundo,'#e5bd79',(14,13,1252,694),2,border_radius=23)
        pygame.draw.rect(fundo,'#58232c',(22,21,1236,678),1,border_radius=18)
        return fundo

    def _criar_paes(self):
        tras=pygame.Surface((LARGURA,ALTURA),pygame.SRCALPHA)
        frente=tras.copy(); rng=random.Random(37)
        # As imagens são exatamente o sprite usado pelo jogo, não novas bolinhas.
        for fila in range(2):
            for i in range(19):
                x=15+i*70+rng.randint(-15,15)
                # Pilha sobe nas bordas, descendo no centro para enquadrar o herói.
                y=488-48*(abs(x-640)/640)**1.5+fila*30+rng.uniform(-14,12)
                lado=rng.randint(77,105) if fila else rng.randint(67,90)
                pao=pygame.transform.rotozoom(self.pao,rng.uniform(-70,70),lado/self.pao.get_width())
                (tras if fila==0 else frente).blit(pao,pao.get_rect(center=(x,y)))
        return tras,frente

    def _criar_graos(self):
        rng=random.Random(12); resultado=[]
        for _ in range(4):
            camada=pygame.Surface((LARGURA,ALTURA),pygame.SRCALPHA)
            for n in range(6500):
                camada.set_at((rng.randrange(LARGURA),rng.randrange(ALTURA)),
                             (255,237,196,rng.randrange(8,23)))
            resultado.append(camada)
        return resultado

    def _calcular_viewport(self,tamanho):
        w,h=tamanho; escala=min(w/LARGURA,h/ALTURA)
        self.viewport=pygame.Rect(0,0,max(1,round(LARGURA*escala)),max(1,round(ALTURA*escala)))
        self.viewport.center=(w//2,h//2)

    def _ponto(self,pos):
        self._calcular_viewport(pygame.display.get_surface().get_size())
        if not self.viewport.collidepoint(pos): return (-100,-100)
        return ((pos[0]-self.viewport.x)*LARGURA/self.viewport.w,
                (pos[1]-self.viewport.y)*ALTURA/self.viewport.h)

    def ativar_audio(self):
        """Inicia a música embutida do menu no canal reservado, se o som estiver ativo."""
        if not self.som or self.canal is not None: return
        try:
            if not pygame.mixer.get_init(): pygame.mixer.init()
            # O canal zero é reservado apenas enquanto a tela está aberta.
            # Isso não carrega nem substitui pygame.mixer.music, usado pela luta.
            pygame.mixer.set_reserved(1)
            self.musica=pygame.mixer.Sound(file=BytesIO(_midia('musica.ogg')))
            self.canal=pygame.mixer.Channel(0)
            self.canal.set_volume(VOLUME_MUSICA)
            self.canal.play(self.musica,loops=-1,fade_ms=250)
        except pygame.error as erro:
            self.aviso_som='Áudio indisponível: '+str(erro)
            self.canal=None
            self.som=False

    def parar_audio(self):
        """Interrompe a música do menu e libera sua reserva de canal."""
        if self.canal is not None:
            self.canal.stop(); self.canal=None
            if pygame.mixer.get_init(): pygame.mixer.set_reserved(0)

    def alternar_som(self):
        """Alterna a preferência local de som e inicia ou interrompe a música do menu."""
        self.som=not self.som
        if self.som: self.ativar_audio()
        else: self.parar_audio()

    def _escolher(self,indice):
        self.selecionado=indice
        self.foco=indice

    def handle_event(self,evento,*,posicao_logica=None):
        """Retorna o número do chefe só ao confirmar INICIAR JOGO."""
        if evento.type==pygame.QUIT:
            self.encerrado=True; self.parar_audio()
        elif evento.type==pygame.WINDOWFOCUSLOST:
            if self.canal: self.canal.pause()
        elif evento.type==pygame.WINDOWFOCUSGAINED:
            if self.canal: self.canal.unpause()
        elif evento.type==pygame.MOUSEMOTION:
            self.mouse=posicao_logica if posicao_logica is not None else self._ponto(evento.pos)
            if self.iniciar_rect.collidepoint(self.mouse): self.foco=-1
            for i,r in enumerate(self.nivel_rects):
                if r.collidepoint(self.mouse): self.foco=i
        elif evento.type==pygame.MOUSEBUTTONDOWN and evento.button==1:
            pos=posicao_logica if posicao_logica is not None else self._ponto(evento.pos)
            if self.som_rect.collidepoint(pos): self.alternar_som()
            elif self.iniciar_rect.collidepoint(pos): return self.confirmar()
            else:
                for i,r in enumerate(self.nivel_rects):
                    if r.collidepoint(pos): self._escolher(i)
        elif evento.type==pygame.KEYDOWN:
            k=evento.key
            if k==pygame.K_ESCAPE:
                self.encerrado=True; self.parar_audio()
            elif k==pygame.K_m: self.alternar_som()
            elif pygame.K_1<=k<=pygame.K_3: self._escolher(k-pygame.K_1)
            elif k in (pygame.K_LEFT,pygame.K_a): self._escolher((self.selecionado-1)%3)
            elif k in (pygame.K_RIGHT,pygame.K_d): self._escolher((self.selecionado+1)%3)
            elif k in (pygame.K_UP,pygame.K_w): self.foco=-1
            elif k in (pygame.K_DOWN,pygame.K_s): self.foco=self.selecionado
            elif k==pygame.K_TAB: self.foco=(self.foco+2)%4-1
            elif k in (pygame.K_RETURN,pygame.K_SPACE,pygame.K_KP_ENTER):
                if self.foco==-1: return self.confirmar()
                self.selecionado=self.foco; self.foco=-1
        return None

    def confirmar(self):
        """Devolve 1, 2 ou 3 para a fase selecionada e interrompe a música do menu."""
        if not self.disponiveis[self.selecionado]: return None
        self.parar_audio()
        return self.selecionado+1

    def update(self,dt):
        """Avança o tempo visual do menu, limitando intervalos grandes entre quadros."""
        self.tempo+=max(0,min(float(dt),.1))

    def draw(self,destino):
        """Desenha logo, personagem, seleção, créditos e controles mantendo a proporção da tela."""
        s=self.canvas; s.blit(self.fundo,(0,0))
        # Letreiro e subtítulo permanecem estáveis para boa leitura.
        s.blit(self.logo,(40,43))
        s.blit(self.pilha_fundo,(0,0))
        # Sequência pingue-pongue evita salto do último para o primeiro desenho.
        ordem=(0,1,2,1,0,5,4,3,4,5)
        quadro=ordem[int(self.tempo*FPS_ANIMACAO)%len(ordem)]
        # Animação desenhada quadro a quadro, sem deslizar os pés pelo cenário.
        frame=self.frames[quadro]
        s.blit(frame,(448,149))
        s.blit(self.pilha_frente,(0,0))
        # Faixa inferior organiza os controles embaixo da ilustração.
        faixa=pygame.Surface((1232,164),pygame.SRCALPHA); faixa.fill((49,17,27,236))
        s.blit(faixa,(24,538))
        pygame.draw.line(s,'#e3b56e',(52,539),(1228,539),2)
        ativo=self.disponiveis[self.selecionado]
        brilho=COR_OURO if self.foco==-1 else COR_CREME
        texto=self._texto('INICIAR JOGO',44,brilho if ativo else '#a7897d',2)
        s.blit(texto,texto.get_rect(center=self.iniciar_rect.center))
        if self.foco==-1:
            seta=self._texto('›',49,COR_OURO,1)
            s.blit(seta,seta.get_rect(midright=(self.iniciar_rect.left-7,self.iniciar_rect.centery-1)))
        dica=self._texto('ESCOLHA SEU DESAFIO',14,'#cf9c76',1)
        s.blit(dica,dica.get_rect(center=(640,620)))
        for i,r in enumerate(self.nivel_rects):
            marcado=i==self.selecionado
            if marcado:
                pygame.draw.rect(s,'#ecca81',r,border_radius=5)
                pygame.draw.rect(s,COR_TINTA,r,2,border_radius=5)
            elif i==self.foco:
                pygame.draw.rect(s,'#75434a',r,border_radius=5)
            nome=self.nomes[i] if self.disponiveis[i] else 'EM BREVE'
            label=f'{i+1:02d}  {nome}'
            cor=COR_OURO if not marcado else COR_CREME
            cel=self._texto(label,22,cor,1)
            if marcado:
                # Mesmo desenho de letra; tinta escura sobre a seleção dourada.
                cel=self.fonte(22).render(label,True,COR_TINTA)
            if cel.get_width()>r.w-15:
                cel=pygame.transform.smoothscale(cel,(r.w-15,cel.get_height()))
            s.blit(cel,cel.get_rect(center=r.center))
        audio=self._texto('M · SOM '+('ON' if self.som else 'OFF'),13,'#e9bd8d',1)
        s.blit(audio,audio.get_rect(center=self.som_rect.center))
        rodape=self._texto('← → / 1 2 3  ESCOLHER     ENTER  INICIAR     ESC  SAIR',12,'#d5ae8e',0)
        s.blit(rodape,rodape.get_rect(center=(410,696)))
        criadores=self._texto(CREATORS_LABEL,14,'#d5ae8e',0)
        s.blit(criadores,criadores.get_rect(center=(920,696)))
        s.blit(self.granulados[int(self.tempo*12)%4],(0,0))
        # Riscos de filme suaves e determinísticos, sem flashes fortes.
        if int(self.tempo*8)%13==0:
            pygame.draw.line(s,'#be7161',(1170,70),(1168,510),1)
        self._calcular_viewport(destino.get_size())
        destino.fill('#160d16')
        if self.viewport.size==s.get_size(): destino.blit(s,self.viewport)
        else: destino.blit(pygame.transform.smoothscale(s,self.viewport.size),self.viewport)


def mostrar_menu(tela=None, *, som=True, nomes=NOMES_CHEFES,
                 disponiveis=(True,True,True), selecionado=1):
    """Abre a tela e devolve 1/2/3. Não fecha o Pygame ao escolher uma fase.

    Se tela foi criada pelo seu jogo, passa a usá-la. ESC/fechar retorna None.
    A música sempre para antes de devolver o controle ao jogo.
    """
    pygame.display.init(); pygame.font.init()
    if tela is None:
        tela=pygame.display.get_surface()
        if tela is None:
            tela=pygame.display.set_mode((1100,619),pygame.RESIZABLE)
    pygame.display.set_caption('Mineirinho — Tela inicial')
    menu=TelaInicial(som=som,nomes=nomes,disponiveis=disponiveis,selecionado=selecionado)
    clock=pygame.time.Clock(); menu.ativar_audio()
    try:
        while not menu.encerrado:
            dt=min(clock.tick(60)/1000,.1)
            for evento in pygame.event.get():
                if evento.type==pygame.VIDEORESIZE:
                    tela=pygame.display.get_surface()
                escolha=menu.handle_event(evento)
                if escolha is not None: return escolha
                if menu.encerrado: break
            if menu.encerrado: break
            menu.update(dt); menu.draw(tela); pygame.display.flip()
        return None
    finally:
        menu.parar_audio()


def criar_app_com_menu(AppOriginal):
    """Adaptador opcional para a arquitetura App do projeto anterior.

    Exige os métodos start_level, handle_event, update e render e atributos
    window, screen, running. Lê as classes de levels.LEVELS por number 1/2/3.
    Não substitui arquivos do jogo ou da fase 2; não faz commits.
    """
    exigidos=('start_level','handle_event','update','render','run')
    if not all(callable(getattr(AppOriginal,n,None)) for n in exigidos):
        raise TypeError('Seu jogo usa outra arquitetura. Integre mostrar_menu() no ponto que abre as fases.')

    class AppComTelaInicial(AppOriginal):
        def __init__(self,*args,**kwargs):
            super().__init__(*args,**kwargs)
            from levels import LEVELS
            self._classes_menu=[next((c for c in LEVELS if getattr(c,'number',None)==n),None) for n in (3,2,1)]
            disponiveis=tuple(c is not None and bool(getattr(c,'available',True)) for c in self._classes_menu)
            self._inicio_novo=TelaInicial(som=kwargs.get('sound',True) and getattr(getattr(self,'audio',None),'enabled',True),
                                          disponiveis=disponiveis)
            self._inicio_mostrado=False

        def _esta_no_menu(self):
            return self.screen in ('home','levels')

        def handle_event(self,evento):
            if not self._esta_no_menu(): return super().handle_event(evento)
            if evento.type==pygame.VIDEORESIZE:
                # Pygame 2 atualiza o display. Não recria janela ou perde contexto.
                self.window=pygame.display.get_surface()
            elif evento.type==pygame.WINDOWFOCUSLOST and hasattr(self,'clear_input'):
                self.clear_input()
            escolha=self._inicio_novo.handle_event(evento)
            if self._inicio_novo.encerrado:
                self.running=False
            elif escolha is not None:
                classe=self._classes_menu[escolha-1]
                if classe and self.start_level(classe.id):
                    self._inicio_mostrado=False
                else:
                    self._inicio_novo.ativar_audio()

        def update(self,dt):
            if self._esta_no_menu():
                self._inicio_novo.update(dt)
                if not self._inicio_mostrado:
                    # Para notas/efeitos da luta antes de entrar no menu.
                    if pygame.mixer.get_init(): pygame.mixer.stop()
                    self._inicio_novo.ativar_audio()
                    self._inicio_mostrado=True
            else:
                self._inicio_novo.parar_audio()
                super().update(dt)

        def render(self):
            if self._esta_no_menu():
                self._inicio_novo.draw(self.window); pygame.display.flip()
            else: super().render()

        def run(self):
            try: return super().run()
            finally: self._inicio_novo.parar_audio()

    return AppComTelaInicial


def _executar_terminal():
    if '--jogar' in sys.argv:
        try:
            from app import App
        except ImportError as erro:
            raise SystemExit('Modo --jogar requer o projeto com app.py e levels/.\n'
                             'Para visualizar só o menu: py tela_inicial.py\nDetalhe: '+str(erro))
        criar_app_com_menu(App)().run()
    else:
        escolha=mostrar_menu(som='--sem-som' not in sys.argv)
        pygame.quit()
        print('Menu encerrado.' if escolha is None else
              f'Chefe {escolha} selecionado. Prévia concluída; use --jogar no projeto com App.')

